add_exam_question(2025, "广东卷", "计算题", "计算0.1mol/L NaOH溶液的pH（25℃）。", [], "13", "c(OH⁻)=0.1mol/L，c(H⁺)=1×10⁻¹³mol/L，pH=13。")
